```typescript
// src/cart.ts

export interface CartItem {
  price: number;
  quantity: number;
}

export interface CartCalculation {
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
}

export function calculateCartTotal(
  items: CartItem[],
  couponCode?: string,
  taxRate: number = 0.08 // default 8% tax
): CartCalculation {
  // Calculate subtotal
  const subtotal = round2(
    items.reduce((sum, item) => sum + item.price * item.quantity, 0)
  );

  // Apply coupon discount
  let discount = 0;
  if (couponCode === 'SAVE10') {
    discount = round2(subtotal * 0.10);
  } else if (couponCode === 'FLAT5') {
    discount = Math.min(5, subtotal); // cannot exceed subtotal
    discount = round2(discount);
  }

  // Calculate taxable amount after discount
  const discountedSubtotal = round2(subtotal - discount);

  // Apply tax on the discounted amount
  const tax = round2(discountedSubtotal * taxRate);

  // Final total
  const total = round2(discountedSubtotal + tax);

  return {
    subtotal,
    discount,
    tax,
    total
  };
}

function round2(num: number): number {
  return Math.round((num + Number.EPSILON) * 100) / 100;
}
```

### Explanation:
- **Subtotal**: Sum of `price * quantity` for all items, rounded to 2 decimals.
- **Discount**:
  - `SAVE10` → 10% off on subtotal.
  - `FLAT5` → $5 off, but capped at the subtotal value (if subtotal is less than $5, discount equals subtotal).
- **Tax**: Applied on the discounted subtotal using the provided `taxRate` (default 8%).
- **Total**: `subtotal - discount + tax`.
- **Rounding**: All values are rounded to 2 decimal places using a safe `round2` helper to avoid floating‑point precision issues.

